import{_ as r,a0 as p,w as e,s as I,ao as u,I as i,x as t,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const O=JSON.parse('{"title":"Linux 下易用的光盤鏡像管理工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下易用的光盤鏡像管理工具 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下易用的光盤鏡像管理工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下易用的光盤鏡像管理工具 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141027 Handy Disk Image Tools","title":"Linux 下易用的光盤鏡像管理工具","tag":"201411","desc":""},"relativePath":"201411/20141027 Handy Disk Image Tools.md","filePath":"[post].md"}'),D={name:"201411/20141027 Handy Disk Image Tools.md"};function S(m,l,d,T,a,f){const n=p("Link");return e(),I("div",null,[l[36]||(l[36]=u('<h1 id="linux-下易用的光盤鏡像管理工具" tabindex="-1">Linux 下易用的光盤鏡像管理工具 <a class="header-anchor" href="#linux-下易用的光盤鏡像管理工具" aria-label="Permalink to “Linux 下易用的光盤鏡像管理工具”">​</a></h1><p>磁盤鏡像包括了整個磁盤卷的文件或者是全部的存儲設備的數據，比如説硬盤，光盤（DVD,CD,藍光光碟），磁帶機，USB閃存，軟盤。一個完整的磁盤鏡像應該包含與原來的存儲設備上一樣完整、準確，包括數據和結構信息。</p><p>磁盤鏡像文件格式可以是採用開放的標準，像ISO格式的光盤鏡像，或者是專有的軟件應用程序的特定格式。&quot;ISO&quot;這個名字來源於用CD存儲的ISO 9660文件系統。但是，當用户轉向Linux的時候，經常遇到這樣的問題，需要把專有的的鏡像格式轉換為開放的格式。</p><p>磁盤鏡像有很多不同的用處，像燒錄光盤，系統備份，數據恢復，硬盤克隆，電子取證和提供操作系統（即LiveCD/DVDs）。</p><p>有很多不同的方法可以把ISO鏡像掛載到Linux系統下。強大的mount 命令給我們提供了一個簡單的解決方案。但是如果你需要很多工具來操作磁盤鏡像，你可以試一試下面的這些強大的開源工具。</p><p>很多工具還沒有看到最新的版本，所以如果你正在尋找一個很好用的開源工具，你也可以加入，一起來為開源做出一點貢獻。</p><h3 id="furius-iso-mount" tabindex="-1">Furius ISO Mount <a class="header-anchor" href="#furius-iso-mount" aria-label="Permalink to “Furius ISO Mount”">​</a></h3><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-FuriusISOMountTool.png" alt=""></p><p>Furius ISO Mount是一個簡單易用的開源應用程序，可以用來掛載鏡像文件，它支持直接打開ISO,IMG,BIN,MDF和NRG格式的鏡像而不用把他們燒錄到磁盤。</p><p>特性：</p><ul><li>支持自動掛載ISO, IMG, BIN, MDF and NRG鏡像文件</li><li>支持通過 loop 方式掛載 UDF 鏡像</li><li>自動在根目錄創建掛載點</li><li>自動解掛鏡像文件</li><li>自動刪除掛載目錄，並返回到主目錄之前的狀態</li><li>自動記錄最近10次掛載歷史</li><li>支持掛載多個鏡像文件</li><li>支持燒錄ISO文件及IMG文件到光盤</li><li>支持MD5校驗和SHA1校驗</li><li>自動檢索之前解掛的鏡像</li><li>自動創建手動掛載和解掛的日誌文件</li><li>語言支持（目前支持保加利亞語，中文（簡體），捷克語，荷蘭語，法語，德語，匈牙利語，意大利語，希臘語，日語，波蘭語，葡萄牙語，俄語，斯洛文尼亞語，西班牙語，瑞典語和土耳其語）</li></ul><hr>',12)),i("ul",null,[i("li",null,[l[1]||(l[1]=t("項目網址： ",-1)),o(n,{href:"https://launchpad.net/furiusisomount/"},{default:s(()=>[...l[0]||(l[0]=[t("launchpad.net/furiusisomount/",-1)])]),_:1})]),l[2]||(l[2]=i("li",null,"開發者: Dean Harris (Marcus Furius)",-1)),l[3]||(l[3]=i("li",null,"許可： GNU GPL v3",-1)),l[4]||(l[4]=i("li",null,"版本號： 0.11.3.1",-1))]),l[37]||(l[37]=u('<p>###fuseiso</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-fuseiso.png" alt=""></p><p>fuseiso 是用來掛載ISO文件系統的一個開源的安全模組。</p><p>使用FUSE，我們完全可以在用户空間裏運行一個完整的文件系統。</p><p>特性：</p><ul><li>支持讀ISO,BIN和NRG鏡像，包括ISO 9660文件系統</li><li>支持普通的ISO 9660級別1和級別2</li><li>支持一些常用的擴展，想Joliet，RockRidge和zisofs</li><li>支持非標準的鏡像，包括CloneCD&#39;s IMGs 、Alcohol 120%&#39;s MDFs 因為他們的格式看起來恰好像BIN鏡像一樣</li></ul><hr>',7)),i("ul",null,[i("li",null,[l[6]||(l[6]=t("項目網址： ",-1)),o(n,{href:"http://sourceforge.net/projects/fuseiso/"},{default:s(()=>[...l[5]||(l[5]=[t("sourceforge.net/projects/fuseiso",-1)])]),_:1})]),l[7]||(l[7]=i("li",null,"開發者： Dmitry Morozhnikov",-1)),l[8]||(l[8]=i("li",null,"許可： GNU GPL v2",-1)),l[9]||(l[9]=i("li",null,"版本號： 20070708",-1))]),l[38]||(l[38]=i("p",null,"###iat",-1)),l[39]||(l[39]=i("p",null,[i("img",{src:"http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-iat.png",alt:""})],-1)),l[40]||(l[40]=i("p",null,"iat（Iso 9660分析工具）是一個通用的開源工具，能夠檢測很多不同鏡像格式文件的結構，包括BIN,MDF,PDI,CDI,NRG和B5I,並轉化成ISO 9660格式.",-1)),l[41]||(l[41]=i("p",null,"特性：",-1)),l[42]||(l[42]=i("ul",null,[i("li",null,"支持讀取（輸入）NRG,MDF,PDI,CDI,BIN,CUE 和B5I鏡像"),i("li",null,"支持用 cd 刻錄機直接燒錄光盤鏡像"),i("li",null,"輸出信息包括：進度條，塊大小，ECC扇形分區（大小），頭分區（大小），鏡像偏移地址等等")],-1)),l[43]||(l[43]=i("hr",null,null,-1)),i("ul",null,[i("li",null,[l[11]||(l[11]=t("項目網址： ",-1)),o(n,{href:"http://sourceforge.net/projects/iat.berlios/"},{default:s(()=>[...l[10]||(l[10]=[t("sourceforge.net/projects/iat.berlios",-1)])]),_:1})]),l[12]||(l[12]=i("li",null,"開發者： Salvatore Santagati",-1)),l[13]||(l[13]=i("li",null,"許可： GNU GPL v2",-1)),l[14]||(l[14]=i("li",null,"版本號： 0.1.3",-1))]),l[44]||(l[44]=u('<p>###AcetoneISO</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-AcetoneISO.png" alt=""></p><p>AcetoneISO 是一個功能豐富的開源圖形化應用程序，用來掛載和管理CD/DVD鏡像。</p><p>當你打開這個程序，你就會看到一個圖形化的文件管理器用來掛載鏡像文件，包括專有的鏡像格式，也包括像ISO, BIN, NRG, MDF, IMG 等等，並且允許您執行一系列的操作。</p><p>AcetoneISO是用QT 4寫的，也就是説，對於基於QT的桌面環境能很好的兼容，像KDE，LXQT或是Razor-qt。</p><p>這個軟件適用於所有正在尋找Linux版本的Daemon Tools的人。</p><p>特性：</p><ul><li>支持掛載大多數windows 鏡像，界面簡潔易用</li><li>可以將其所有支持鏡像格式轉換到ISO,或者是從中提取內容</li><li>加密，壓縮，解壓任何類型的鏡像</li><li>轉換DVD成xvid avi，支持將各種常規視頻格式轉換成xvid avi</li><li>從視頻裏提取聲音</li><li>從不同格式中提取鏡像中的文件，包括bin mdf nrg img daa dmg cdi b5i bwi pdi</li><li>用Kaffeine / VLC / SMplayer播放DVD鏡像，可以從Amazon 自動下載封面。</li><li>從文件夾或者是CD/DVD生成ISO鏡像</li><li>可以做鏡像的MD5校驗，或者是生成鏡像的MD5校驗碼</li><li>計算鏡像的ShaSums（128,256和384位）</li><li>支持加密，解密一個鏡像文件</li><li>按兆數分拆和合並鏡像</li><li>以高壓縮比將鏡像壓縮成7z 格式</li><li>翻錄PSX CD成BIN格式，以便在ePSXe/pSX模擬器裏運行</li><li>為BIN和IMG格式恢復丟失的 CUE 文件</li><li>把MAC OS的DMG鏡像轉換成可掛載的鏡像</li><li>從指定的文件夾中掛載鏡像</li><li>創建資料庫來管理一個大的鏡像集合</li><li>從CD/DVD 或者是ISO鏡像中提取啓動文件</li><li>備份CD成BIN鏡像</li><li>簡單快速的把DVD翻錄成Xvid AVI</li><li>簡單快速的把常見的視頻（avi, mpeg, mov, wmv, asf）轉換成Xvid AVI</li><li>簡單快速的把FLV 換換成AVI 格式</li><li>從YouTube和一些視頻網站下載視頻</li><li>提取一個有密碼的RAR存檔</li><li>支持轉換任何的視頻到PSP上</li><li>國際化的語言支持支持（英語，意大利語，波蘭語，西班牙語，羅馬尼亞語，匈牙利語，德語，捷克語和俄語）</li></ul><hr>',9)),i("ul",null,[i("li",null,[l[16]||(l[16]=t("項目網址: ",-1)),o(n,{href:"http://sourceforge.net/projects/acetoneiso/"},{default:s(()=>[...l[15]||(l[15]=[t("sourceforge.net/projects/acetoneiso",-1)])]),_:1})]),l[17]||(l[17]=i("li",null,"開發者: Marco Di Antonio",-1)),l[18]||(l[18]=i("li",null,"許可: GNU GPL v3",-1)),l[19]||(l[19]=i("li",null,"版本號: 2.3",-1))]),l[45]||(l[45]=u('<p>###ISO Master</p><p><img src="http://www.linuxlinks.com/portal/content/reviews/Utilities/Screenshot-ISOMaster.png" alt=""></p><p>ISO Master是一個開源、易用的、圖形化CD 鏡像編輯器，適用於Linux 和BSD 。可以從ISO 裏提取文件，給ISO 裏面添加文件，創建一個可引導的ISO，這些都是在一個可視化的用户界面完成的。可以打開ISO，NRG 和一些MDF文件，但是隻能保存成ISO 格式。</p><p>ISO Master 是基於bkisofs 創建的，這是一個簡單、穩定的閲讀，修改和編寫ISO 鏡像的軟件庫，支持Joliet, RockRidge 和EL Torito擴展，</p><p>特性：</p><ul><li>支持讀ISO 格式文件（ISO9660, Joliet, RockRidge 和 El Torito），大多數的NRG 格式文件和一些單軌道的MDF文件，但是，只能保存成ISO 格式</li><li>創建和修改一個CD/DVD 格式文件</li><li>支持CD 格式文件的添加或刪除文件和目錄</li><li>支持創建可引導的CD/DVD</li><li>國際化的支持</li></ul><hr>',7)),i("ul",null,[i("li",null,[l[21]||(l[21]=t("項目網址: ",-1)),o(n,{href:"http://www.littlesvr.ca/isomaster/"},{default:s(()=>[...l[20]||(l[20]=[t("www.littlesvr.ca/isomaster/",-1)])]),_:1})]),l[22]||(l[22]=i("li",null,"開發者: Andrew Smith",-1)),l[23]||(l[23]=i("li",null,"許可: GNU GPL v2",-1)),l[24]||(l[24]=i("li",null,"版本號: 1.3.11",-1))]),l[46]||(l[46]=i("hr",null,null,-1)),i("p",null,[l[26]||(l[26]=t("via: ",-1)),o(n,{href:"http://www.linuxlinks.com/article/20141025082352476/DiskImageTools.html"},{default:s(()=>[...l[25]||(l[25]=[t("http://www.linuxlinks.com/article/20141025082352476/DiskImageTools.html",-1)])]),_:1})]),i("p",null,[l[29]||(l[29]=t("作者：Frazer Kline 譯者：",-1)),o(n,{href:"https://github.com/barney-ro"},{default:s(()=>[...l[27]||(l[27]=[t("barney-ro",-1)])]),_:1}),l[30]||(l[30]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...l[28]||(l[28]=[t("wxy",-1)])]),_:1})]),i("p",null,[l[33]||(l[33]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...l[31]||(l[31]=[t("LCTT",-1)])]),_:1}),l[34]||(l[34]=t(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...l[32]||(l[32]=[t("Linux中國",-1)])]),_:1}),l[35]||(l[35]=t(" 榮譽推出",-1))])])}const g=r(D,[["render",S]]);export{O as __pageData,g as default};
